mapper.select:
SELECT * FROM (
    SELECT a.* FROM CONTRACT_REVIEW_STEP_ATTEMPT a
    JOIN CONTRACT_REVIEW_STEP s ON s.RUN_ID = a.RUN_ID AND s.STEP_ID = a.STEP_ID
    JOIN CONTRACT_REVIEW_RUN r ON r.RUN_ID = a.RUN_ID
    WHERE a.STATUS = 'RUNNING' AND s.STATUS = 'RUNNING'
      AND s.CURRENT_ATTEMPT_NO = a.ATTEMPT_NO
      AND r.STATUS IN ('RUNNING', 'UNKNOWN')
      AND a.LEASE_OWNER IS NOT NULL AND a.LEASE_UNTIL <= #{now}
    ORDER BY a.LEASE_UNTIL, a.ATTEMPT_ID
) WHERE ROWNUM <= #{limit}

mapper.update:
UPDATE CONTRACT_REVIEW_STEP_ATTEMPT SET
    STATUS = #{next.status}, LEASE_OWNER = #{next.leaseOwner}, LEASE_UNTIL = #{next.leaseUntil},
    CLAIMED_AT = #{next.claimedAt}, EXTERNAL_CALL_STATE = #{next.externalCallState},
    EXTERNAL_REQUEST_FINGERPRINT = #{next.externalRequestFingerprint},
    PROVIDER_REQUEST_ID = #{next.providerRequestId}, PROVIDER = #{next.provider}, "MODEL" = #{next.model},
    STARTED_AT = #{next.startedAt}, COMPLETED_AT = #{next.completedAt},
    SAFE_REASON_CODE = #{next.safeReasonCode}, OUTPUT_RESOURCE_TYPE = #{next.outputResourceType},
    OUTPUT_RESOURCE_ID = #{next.outputResourceId}, VERSION_NO = #{next.versionNo}
WHERE ATTEMPT_ID = #{expected.attemptId} AND RUN_ID = #{expected.runId}
  AND STEP_ID = #{expected.stepId} AND ATTEMPT_NO = #{expected.attemptNo}
  AND STATUS = #{expected.status} AND VERSION_NO = #{expected.versionNo}
  AND OPERATION_IDENTITY = #{expected.operationIdentity}
  AND EXISTS (SELECT 1 FROM CONTRACT_REVIEW_STEP s
      WHERE s.RUN_ID = #{expected.runId} AND s.STEP_ID = #{expected.stepId}
        AND s.CURRENT_ATTEMPT_NO = #{expected.attemptNo} AND s.STATUS = #{expected.status})


        AND STATUS = 'PENDING' AND LEASE_OWNER IS NULL AND LEASE_UNTIL IS NULL
        AND EXTERNAL_CALL_STATE = 'NOT_STARTED'


        AND STATUS = 'RUNNING' AND LEASE_OWNER = #{expected.leaseOwner} AND LEASE_UNTIL > #{now}


        AND STATUS = 'RUNNING' AND LEASE_OWNER = #{expected.leaseOwner} AND LEASE_UNTIL <= #{now}

    AND 1 = 0
